import {CATALOG} from '../catalog.mjs';
const $=s=>document.querySelector(s), drafts=new Map();
let snapshot={revision:0,overrides:{}},csrf='',role='',busy=false,loaded=false;
const effective=(item,s=snapshot)=>s.overrides[item.id]??item.name;
const value=item=>drafts.has(item.id)?drafts.get(item.id):effective(item);
function status(message='',error=false){$('#status').textContent=message;$('#status').classList.toggle('error',error);}
async function api(path,options={}){const response=await fetch('/api/atlas/'+path,{credentials:'same-origin',...options,headers:{...(options.body?{'Content-Type':'application/json'}:{}),...(csrf?{'X-CSRF-Token':csrf}:{}),...options.headers}});let data;try{data=await response.json();}catch{data={};}if(!response.ok||data.ok===false){const error=new Error(data.message||data.error||'Operazione non riuscita. Riprova.');error.status=response.status;throw error;}return data;}
function updateCount(){const count=drafts.size;$('#change-count').textContent=count?`${count} ${count===1?'modifica da salvare':'modifiche da salvare'}`:'Nessuna modifica';$('#save').disabled=busy||!count;$('#discard').disabled=busy||!count;}
function draft(item,text){const normalized=text.trim();if(normalized===effective(item))drafts.delete(item.id);else drafts.set(item.id,text);updateCount();}
function render(){const query=$('#search').value.trim().toLocaleLowerCase('it'),group=$('#group').value;const items=CATALOG.filter(item=>(!group||item.group===group)&&(!query||[item.name,value(item),item.group].some(v=>String(v).toLocaleLowerCase('it').includes(query))));$('#results').textContent=`${items.length} ${items.length===1?'luogo':'luoghi'}`;$('#empty').hidden=!!items.length;$('#items').replaceChildren(...items.map(item=>{const row=document.createElement('div');row.className='item'+(drafts.has(item.id)?' dirty':'');const original=document.createElement('div');original.className='original';original.textContent=item.name;const meta=document.createElement('div');meta.className='meta';meta.textContent=[item.group,item.kind].filter(Boolean).join(' · ');original.append(meta);const label=document.createElement('label'),caption=document.createElement('span'),input=document.createElement('input');caption.textContent='Nome nell’atlante';input.value=value(item);input.maxLength=80;input.setAttribute('aria-label',`Nome di ${item.name}`);input.dataset.id=item.id;input.disabled=busy;input.addEventListener('input',()=>{draft(item,input.value);row.classList.toggle('dirty',drafts.has(item.id));});label.append(caption,input);const reset=document.createElement('button');reset.type='button';reset.className='reset';reset.textContent='Ripristina originale';reset.setAttribute('aria-label',`Ripristina ${item.name}`);reset.disabled=busy;reset.onclick=()=>{draft(item,item.name);render();};row.append(original,label,reset);return row;}));updateCount();}
function signedOut(message=''){csrf='';role='';$('#auth').hidden=false;$('#editor').hidden=true;$('#logout').hidden=true;status(message);}
async function enter(session){csrf=session.csrf||'';role=session.role||'';$('#auth').hidden=true;if(role!=='admin'){$('#editor').hidden=true;$('#logout').hidden=false;status('Il tuo account non dispone dei permessi per modificare l’atlante.');return;}$('#editor').hidden=false;$('#logout').hidden=false;$('#identity').textContent=session.user?.username||session.user||'Amministratore';if(!loaded){snapshot=await api('names');loaded=true;}render();status(drafts.size?'Accesso effettuato. Le modifiche in sospeso sono ancora disponibili.':'');}
$('#theme').onclick=()=>{const dark=document.documentElement.dataset.theme!=='dark';document.documentElement.dataset.theme=dark?'dark':'light';$('#theme').textContent=dark?'Tema chiaro':'Tema scuro';$('#theme').setAttribute('aria-pressed',String(dark));};
for(const group of [...new Set(CATALOG.map(item=>item.group))].sort((a,b)=>a.localeCompare(b,'it'))){const option=document.createElement('option');option.value=option.textContent=group;$('#group').append(option);}
$('#search').oninput=render;$('#group').onchange=render;
$('#login').onsubmit=async event=>{event.preventDefault();const form=event.currentTarget,button=form.querySelector('button[type=submit]');button.disabled=true;$('#login-error').hidden=true;try{const username=form.elements.username.value.trim();const session=await api('session',{method:'POST',body:JSON.stringify({username,password:form.elements.password.value,remember:form.elements.remember.checked})});form.elements.password.value='';await enter({...session,user:session.user||username});}catch(error){form.elements.password.value='';$('#login-error').textContent=error.message;$('#login-error').hidden=false;}finally{button.disabled=false;}};
$('#discard').onclick=()=>{drafts.clear();render();status('Modifiche annullate.');};
$('#save').onclick=async()=>{if(busy||role!=='admin')return;const changes=[];for(const[id,text]of drafts){const name=text.trim(),item=CATALOG.find(item=>item.id===id);if(!name||name.length>80||/[\u0000-\u001f\u007f-\u009f]/u.test(name)){status('Ogni nome deve contenere da 1 a 80 caratteri, senza caratteri di controllo.',true);document.querySelector(`[data-id="${CSS.escape(id)}"]`)?.focus();return;}changes.push({id,name:name===item.name?null:name});}busy=true;render();status('Salvataggio…');try{snapshot=await api('names',{method:'PATCH',body:JSON.stringify({revision:snapshot.revision,changes})});drafts.clear();$('#reload').hidden=true;status('Nomi salvati. L’atlante è aggiornato.');}catch(error){if(error.status===401)signedOut('La sessione è scaduta. Accedi di nuovo per salvare: le tue modifiche sono conservate.');else if(error.status===409){status('I nomi sono stati aggiornati da un altro amministratore. Ricarica prima di salvare: le tue modifiche saranno conservate.',true);$('#reload').hidden=false;}else status(error.message,true);}finally{busy=false;render();}};
$('#reload').onclick=async()=>{try{snapshot=await api('names');for(const[id,text]of drafts){const item=CATALOG.find(item=>item.id===id);if(text.trim()===effective(item))drafts.delete(id);}render();$('#reload').hidden=true;status('Nomi aggiornati. Controlla le modifiche in sospeso e salva.');}catch(error){status(error.message,true);}};
$('#logout').onclick=async()=>{try{await api('session',{method:'DELETE'});signedOut(drafts.size?'Accesso terminato. Le modifiche restano disponibili in questa pagina.':'Accesso terminato.');}catch(error){status(error.message,true);}};
window.addEventListener('beforeunload',event=>{if(drafts.size){event.preventDefault();event.returnValue='';}});
try{await enter(await api('session'));}catch(error){if(error.status===401)signedOut();else signedOut('Impossibile verificare l’accesso. Puoi riprovare ad accedere.');}
